    /// Print `fixture` into a fresh 61-column pane and finish every task it asks for.
    fn accept_session(fixture: &[&str], raster: &MathRaster) -> DualPlaneSession {
        let mut session = DualPlaneSession::new(nz(61), nz(4));
        for line in fixture {
            session.feed(line.as_bytes()).unwrap();
            session.feed(b"\r\n").unwrap();
            drain_tasks(&mut session, raster);
        }
        for _ in 0..4 {
            session.feed(b"tail\r\n").unwrap();
            drain_tasks(&mut session, raster);
        }
        session
    }

    /// PIN — every shape the 2026-09-09 acceptance run found undrawn is drawn, in the session and
    /// not only in the recogniser: a row of three physical lines, a row of four, a row whose own
    /// continuation is wider than the pane, and the report's whole table at the width it was
    /// printed at, breaks beside a cell separator and all.
    #[test]
    fn every_shape_the_acceptance_run_found_undrawn_is_drawn_whole() {
        let raster = synthetic_raster(300, 40);
        // Every fixture is read before anything is asserted, so a red run names all of them
        // rather than the first: `None` is a table nobody drew, and the number is the rows the
        // one table drawn resolved to, heading and rule included.
        let drawn: Vec<(&str, Option<usize>)> = [
            ("w5", &ACCEPT_W5[..]),
            ("w6", &ACCEPT_W6[..]),
            ("w8", &ACCEPT_W8[..]),
            ("t", &ACCEPT_T[..]),
            ("p", &ACCEPT_P[..]),
        ]
        .into_iter()
        .map(|(name, fixture)| {
            let session = accept_session(fixture, &raster);
            let sources = table_sources(&session);
            let rows = (sources.len() == 1).then(|| sources[0].lines().count());
            (name, rows)
        })
        .collect();
        assert_eq!(
            drawn,
            vec![
                ("w5", Some(3)),
                ("w6", Some(3)),
                ("w8", Some(3)),
                ("t", Some(7)),
                ("p", Some(7)),
            ],
            "one table each, with the heading, the rule and every row of it"
        );
    }

    /// PIN — and the acceptance run's negative still takes the whole table down.
    #[test]
    fn the_acceptance_negative_is_drawn_nowhere() {
        let raster = synthetic_raster(300, 40);
        let session = accept_session(&ACCEPT_W7N, &raster);
        assert!(
            table_sources(&session).is_empty(),
            "a row with a cell missing refuses the table it stands in"
        );
        assert_eq!(ready_tables(&session), 0);
    }

    /// PIN: a row the printing program wrapped is one row, and dragging the pane does not un-join
    /// it.
    ///
    /// The join is over the bytes the program printed and the width it printed them at, and both
    /// are frozen: the transcript never rewrites a finalized line, and `captured_columns` is the
    /// grid the row came off rather than the grid it is being read on. So the second reading, after
    /// a resize, is the first reading.
    #[test]
    fn a_rejoined_row_survives_a_resize_as_one_row() {
        let mut session = DualPlaneSession::new(nz(15), nz(1));
        let raster = synthetic_raster(300, 40);
        // `four | five and` is exactly fifteen cells, so it filled the row it was printed on.
        for line in [
            "a | b | c",
            "--- | --- | ---",
            "one | two | 3",
            "four | five and",
            "six | seven",
            "tail",
        ] {
            session.feed(line.as_bytes()).unwrap();
            session.feed(b"\r\n").unwrap();
            drain_tasks(&mut session, &raster);
        }
        let joined = "| a | b | c |
|---|---|---|
| one | two | 3 |
| four | five and six | seven |";
        assert_eq!(
            table_sources(&session),
            vec![joined.to_owned()],
            "the two printed lines are one row"
        );
        let at = Instant::now();
        session.resize_at(nz(40), nz(1), at).unwrap();
        session.mark_pty_resize_requested_at(nz(40), nz(1), at);
        assert!(
            session
                .finish_resize_if_quiescent(at + Duration::from_millis(400))
                .unwrap()
        );
        drain_tasks(&mut session, &raster);
        assert_eq!(
            table_sources(&session),
            vec![joined.to_owned()],
            "and they are still one row on a wider pane"
        );
    }

    /// PIN: a table streams in and the block grows with it, which is what the arming rule is for.
    /// One record, keyed at the header, ending further down each time a row lands.
    ///
    /// A one-row grid so that every line freezes the moment the next one arrives: this is the
    /// frozen plane's own account of streaming, and a taller grid would keep the whole table live
    /// and prove nothing about it.
    #[test]
    fn a_table_arriving_a_row_at_a_time_grows_one_block_rather_than_stacking_them() {
        let mut session = DualPlaneSession::new(nz(60), nz(1));
        let raster = synthetic_raster(300, 40);
        let mut ends = Vec::new();
        for line in [
            "| name | count |",
            "| --- | ---: |",
            "| alpha | 3 |",
            "| beta | 41 |",
            "tail",
        ] {
            session.feed(line.as_bytes()).unwrap();
            session.feed(b"\r\n").unwrap();
            drain_tasks(&mut session, &raster);
            ends.push(
                session
                    .decorations
                    .values()
                    .filter(|record| {
                        record
                            .span
                            .as_ref()
                            .is_some_and(|span| span.kind == BlockKind::Table)
                    })
                    .filter_map(|record| record.block_end)
                    .max(),
            );
        }
        assert_eq!(
            ends,
            vec![
                None,
                Some(TranscriptId(2)),
                Some(TranscriptId(3)),
                Some(TranscriptId(4)),
                Some(TranscriptId(4)),
            ],
            "a header row alone is not a table; the delimiter row proves one the moment it \
             freezes; every row after it extends the same block; and the line that is not a row \
             ends it where it stood"
        );
        assert_eq!(
            ready_tables(&session),
            1,
            "one table is one block, however it arrived"
        );
    }
